<script setup>
import { reactive,ref } from 'vue'
import { onShow,onHide,onUnload } from '@dcloudio/uni-app'
import AppNavBar from './AppNavBar.vue'
import InitialMealPlan from './InitialMealPlan.vue'
import { createHealthPlanClient,healthPlanState } from '../services/health-plan-client.js'
const active=ref(false)
const state=reactive(healthPlanState()),client=createHealthPlanClient({state})
function open(plan){uni.navigateTo({url:'/pages/health/plans?memberId='+encodeURIComponent(state.memberId)+'&planId='+encodeURIComponent(plan.plan_id)})}
onShow(async()=>{active.value=true;await client.open()});onHide(()=>{active.value=false;client.discard()});onUnload(()=>{active.value=false;client.discard()})
</script>
<template><view class="screen plans-screen"><AppNavBar><view class="nav-row"><button class="icon-button" @click="uni.navigateBack()">‹</button><text class="nav-title">AI专属计划</text></view></AppNavBar><view class="plans-head"><text class="eyebrow">FOR YOUR FAMILY</text><text class="display-title">为您安排的专属计划</text><text class="head-desc">根据真实资料生成的餐单，核对后再决定是否使用。</text></view><view class="choices"><button v-for="m in state.members" :key="m.id" :class="{active:state.memberId===m.id}" :disabled="state.busy" @click="client.open(m.id)">{{m.display_name}}</button></view><text v-if="state.busy" class="safe-note">正在读取计划…</text><text v-if="state.error" class="inline-error">{{state.error}}</text><button v-if="state.error" class="secondary-button" :disabled="state.busy" @click="client.open(state.memberId)">重新读取</button><InitialMealPlan v-if="active && state.memberId" :member-id="state.memberId" @saved="client.page(0)"/><view class="plan-list"><button v-for="plan in state.plans" :key="plan.plan_id" class="plan-card card" @click="open(plan)"><view class="plan-copy"><text class="plan-tag">已保存餐单</text><text class="plan-name">{{plan.plan_date}} 的三餐安排</text><text class="plan-subtitle">版本 {{plan.version}} · 查看菜品、个人份量与使用状态</text><text class="link">查看计划 ›</text></view></button></view><view v-if="!state.busy&&!state.error&&!state.plans.length" class="card plan-card"><text class="section-title">还没有已保存的计划</text><text>可在上方选择日期，生成并确认保存当天三餐。</text></view><button v-if="state.nextOffset!==null" class="secondary-button" :disabled="state.busy" @click="client.page(state.nextOffset)">更多计划</button><view class="review-card card"><text class="section-title">多日计划</text><text>连续21天计划与分批配送服务尚未开放。开通前不展示示例价格，也不创建购买订单。</text></view></view></template>
<style scoped>.plans-head{display:flex;flex-direction:column;gap:16rpx;margin:42rpx 0 28rpx}.display-title{font-size:46rpx}.head-desc{font-size:26rpx;color:#687a72;line-height:1.7}.choices{display:flex;gap:12rpx;flex-wrap:wrap}.choices button{padding:16rpx;background:#f0f3f1;font-size:26rpx;border-radius:16rpx}.choices .active{background:#246b50;color:#fff}.plan-list{display:flex;flex-direction:column;gap:24rpx;margin-top:24rpx}.plan-card,.plan-copy,.review-card{display:flex;flex-direction:column;gap:18rpx;text-align:left}.plan-card,.review-card{width:100%;padding:30rpx;margin:20rpx 0;font-size:26rpx;line-height:1.7}.plan-tag,.link{color:#246b50;font-size:25rpx}.plan-name{font-size:34rpx;font-weight:700}.plan-subtitle{font-size:25rpx;color:#687a72}</style>
